[metadata] {"type": "create", "filePath": "/app/output/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Frontier AI Models Compared - Infographic</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --bg: #0d1117;
    --surface: #161b22;
    --surface2: #1c2130;
    --border: #30363d;
    --blue: #58a6ff;
    --teal: #39d0c9;
    --amber: #f0a234;
    --red: #ff6b6b;
    --green: #56d364;
    --purple: #bc8cff;
    --text: #e6edf3;
    --muted: #8b949e;
    --dim: #484f58;
    --w: 2480px;
    --col-gap: 40px;
  }

  body {
    background: var(--bg);
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    color: var(--text);
    width: var(--w);
    min-height: 3508px;
    padding: 80px 100px 80px;
    font-size: 28px;
    line-height: 1.5;
  }

  /* ── HEADER ── */
  .header {
    display: flex;
    flex-direction: column;
    gap: 20px;
    margin-bottom: 64px;
    padding-bottom: 56px;
    border-bottom: 1px solid var(--border);
  }

  .header-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  .badge {
    background: linear-gradient(135deg, #1a2744 0%, #162240 100%);
    border: 1px solid #2a4a8a;
    color: var(--blue);
    font-size: 22px;
    font-weight: 600;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    padding: 10px 24px;
    border-radius: 6px;
  }

  .source {
    color: var(--muted);
    font-size: 24px;
    font-weight: 400;
  }

  h1 {
    font-size: 88px;
    font-weight: 900;
    line-height: 1.05;
    letter-spacing: -0.03em;
    background: linear-gradient(135deg, #ffffff 0%, #a8c8ff 60%, #39d0c9 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    max-width: 1800px;
  }

  .subtitle {
    color: var(--muted);
    font-size: 32px;
    font-weight: 400;
    max-width: 1600px;
    line-height: 1.6;
  }

  /* ── HERO STATS ── */
  .hero-stats {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 28px;
    margin-bottom: 64px;
  }

  .stat-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 40px;
    display: flex;
    flex-direction: column;
    gap: 10px;
    position: relative;
    overflow: hidden;
  }

  .stat-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
  }
  .stat-card.blue::before { background: linear-gradient(90deg, var(--blue), var(--teal)); }
  .stat-card.amber::before { background: linear-gradient(90deg, var(--amber), #f97316); }
  .stat-card.green::before { background: linear-gradient(90deg, var(--green), var(--teal)); }
  .stat-card.red::before { background: linear-gradient(90deg, var(--red), var(--purple)); }

  .stat-label {
    color: var(--muted);
    font-size: 22px;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.08em;
  }

  .stat-value {
    font-size: 80px;
    font-weight: 900;
    line-height: 1;
    letter-spacing: -0.04em;
  }

  .stat-value.blue { color: var(--blue); }
  .stat-value.amber { color: var(--amber); }
  .stat-value.green { color: var(--green); }
  .stat-value.red { color: var(--red); }

  .stat-unit {
    color: var(--muted);
    font-size: 24px;
    font-weight: 400;
  }

  .stat-context {
    color: var(--dim);
    font-size: 20px;
    line-height: 1.4;
  }

  /* ── SECTION LAYOUT ── */
  .section-title {
    font-size: 40px;
    font-weight: 700;
    letter-spacing: -0.02em;
    margin-bottom: 32px;
    display: flex;
    align-items: center;
    gap: 16px;
  }

  .section-title .pill {
    font-size: 20px;
    font-weight: 600;
    padding: 4px 16px;
    border-radius: 100px;
    letter-spacing: 0.06em;
  }

  .pill.blue { background: rgba(88,166,255,0.15); color: var(--blue); }
  .pill.amber { background: rgba(240,162,52,0.15); color: var(--amber); }
  .pill.teal { background: rgba(57,208,201,0.15); color: var(--teal); }

  .three-col {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: var(--col-gap);
    margin-bottom: 48px;
  }

  .col-block {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 40px;
    display: flex;
    flex-direction: column;
    gap: 8px;
  }

  /* ── BAR CHARTS ── */
  .bar-row {
    display: flex;
    align-items: center;
    gap: 20px;
    margin-bottom: 14px;
  }

  .bar-model {
    width: 380px;
    flex-shrink: 0;
    font-size: 26px;
    font-weight: 500;
    color: var(--text);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .bar-model.dim { color: var(--muted); }

  .bar-track {
    flex: 1;
    height: 34px;
    background: var(--surface2);
    border-radius: 6px;
    overflow: hidden;
    position: relative;
  }

  .bar-fill {
    height: 100%;
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    padding-right: 12px;
    font-size: 22px;
    font-weight: 700;
    color: rgba(255,255,255,0.9);
    white-space: nowrap;
    min-width: 60px;
    transition: width 0.3s;
  }

  .bar-val {
    width: 130px;
    flex-shrink: 0;
    text-align: right;
    font-size: 26px;
    font-weight: 700;
    font-variant-numeric: tabular-nums;
  }

  /* Intelligence gradient: electric blue → teal */
  .intel-fill { background: linear-gradient(90deg, #1e4e8c, var(--blue)); }
  .intel-val { color: var(--blue); }

  /* Speed gradient: teal → green */
  .speed-fill { background: linear-gradient(90deg, #0f4a46, var(--teal)); }
  .speed-val { color: var(--teal); }

  /* Price gradient: amber → red (higher = more expensive) */
  .price-fill { background: linear-gradient(90deg, #3d2200, var(--amber)); }
  .price-val { color: var(--amber); }

  .top-badge {
    display: inline-block;
    font-size: 18px;
    font-weight: 700;
    padding: 2px 10px;
    border-radius: 4px;
    margin-left: 8px;
    vertical-align: middle;
  }
  .top-badge.gold { background: rgba(240,162,52,0.2); color: var(--amber); }
  .top-badge.silver { background: rgba(139,148,158,0.2); color: var(--muted); }

  /* ── DIVIDER ── */
  .divider {
    border: none;
    border-top: 1px solid var(--border);
    margin: 60px 0;
  }

  /* ── TRADE-OFF MATRIX ── */
  .tradeoff-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 28px;
    margin-bottom: 40px;
  }

  .tradeoff-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 40px;
    position: relative;
    overflow: hidden;
  }

  .tradeoff-card::before {
    content: '';
    position: absolute;
    inset: 0;
    opacity: 0.04;
  }

  .tradeoff-card.champion { border-color: #2a5a3a; }
  .tradeoff-card.champion::before { background: var(--green); }
  .tradeoff-card.speed { border-color: #1a4a48; }
  .tradeoff-card.speed::before { background: var(--teal); }
  .tradeoff-card.balanced { border-color: #2a3a6a; }
  .tradeoff-card.balanced::before { background: var(--blue); }
  .tradeoff-card.premium { border-color: #3a2a5a; }
  .tradeoff-card.premium::before { background: var(--purple); }

  .tc-tag {
    font-size: 19px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 12px;
    opacity: 0.7;
  }

  .tc-model {
    font-size: 36px;
    font-weight: 800;
    line-height: 1.1;
    margin-bottom: 20px;
    letter-spacing: -0.02em;
  }

  .tc-metrics {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .tc-metric {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 8px 14px;
    background: rgba(255,255,255,0.04);
    border-radius: 8px;
    font-size: 23px;
  }

  .tc-metric-label { color: var(--muted); }
  .tc-metric-val { font-weight: 700; }

  .tc-metric-val.blue { color: var(--blue); }
  .tc-metric-val.teal { color: var(--teal); }
  .tc-metric-val.amber { color: var(--amber); }
  .tc-metric-val.green { color: var(--green); }
  .tc-metric-val.purple { color: var(--purple); }

  .tc-desc {
    margin-top: 18px;
    font-size: 22px;
    color: var(--muted);
    line-height: 1.5;
  }

  /* ── SCATTER PLOT ── */
  .scatter-wrap {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 48px;
    margin-bottom: 48px;
  }

  .scatter-title {
    font-size: 34px;
    font-weight: 700;
    margin-bottom: 8px;
  }

  .scatter-sub {
    color: var(--muted);
    font-size: 22px;
    margin-bottom: 40px;
  }

  .scatter-svg {
    display: block;
    width: 100%;
  }

  /* ── INSIGHT ROW ── */
  .insight-row {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 28px;
    margin-bottom: 48px;
  }

  .insight-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 32px;
  }

  .insight-icon {
    font-size: 40px;
    margin-bottom: 12px;
    line-height: 1;
  }

  .insight-head {
    font-size: 26px;
    font-weight: 700;
    margin-bottom: 8px;
    line-height: 1.3;
  }

  .insight-body {
    font-size: 22px;
    color: var(--muted);
    line-height: 1.5;
  }

  /* ── METHODOLOGY ── */
  .method-block {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 48px;
    display: grid;
    grid-template-columns: 1fr 2fr;
    gap: 60px;
    align-items: start;
  }

  .method-num {
    font-size: 120px;
    font-weight: 900;
    color: var(--blue);
    line-height: 1;
    letter-spacing: -0.05em;
    opacity: 0.6;
  }

  .method-label {
    color: var(--muted);
    font-size: 24px;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-top: 16px;
  }

  .method-right h3 {
    font-size: 38px;
    font-weight: 700;
    margin-bottom: 16px;
    letter-spacing: -0.02em;
  }

  .method-right p {
    color: var(--muted);
    font-size: 26px;
    line-height: 1.6;
    margin-bottom: 24px;
  }

  .eval-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
  }

  .eval-chip {
    background: var(--surface2);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 6px 18px;
    font-size: 20px;
    color: var(--muted);
    font-weight: 500;
  }

  /* ── FOOTER ── */
  .footer {
    margin-top: 60px;
    padding-top: 32px;
    border-top: 1px solid var(--border);
    display: flex;
    justify-content: space-between;
    align-items: center;
    color: var(--dim);
    font-size: 22px;
  }

  /* highlight rows */
  .bar-row.highlight .bar-model { color: var(--text); font-weight: 700; }

  /* speed leader note */
  .speed-note {
    background: rgba(57,208,201,0.06);
    border: 1px solid rgba(57,208,201,0.2);
    border-radius: 10px;
    padding: 18px 28px;
    font-size: 23px;
    color: var(--teal);
    margin-top: 20px;
    display: flex;
    align-items: center;
    gap: 12px;
  }

  .intel-note {
    background: rgba(88,166,255,0.06);
    border: 1px solid rgba(88,166,255,0.2);
    border-radius: 10px;
    padding: 18px 28px;
    font-size: 23px;
    color: var(--blue);
    margin-top: 20px;
    display: flex;
    align-items: center;
    gap: 12px;
  }

  .price-note {
    background: rgba(240,162,52,0.06);
    border: 1px solid rgba(240,162,52,0.2);
    border-radius: 10px;
    padding: 18px 28px;
    font-size: 23px;
    color: var(--amber);
    margin-top: 20px;
    display: flex;
    align-items: center;
    gap: 12px;
  }

  .big-x {
    font-size: 38px;
    font-weight: 900;
    color: var(--amber);
  }
</style>
</head>
